internal static class WebSocketTests {
    static void Require(bool condition,string message){if(!condition)throw new InvalidDataException(message);}
    sealed class FakeProxy : IDisposable {
        readonly TcpListener server=new TcpListener(IPAddress.Loopback,0);internal int Count;internal string Target;bool done;
        internal int Port {get{return ((IPEndPoint)server.LocalEndpoint).Port;}}
        internal FakeProxy(){server.Start();Task.Run(()=>{while(!done)try{var client=server.AcceptTcpClient();Task.Run(()=>{using(client){try{var stream=client.GetStream();stream.ReadTimeout=3000;Target=WebSocketNetwork.ReadHeader(stream).Split('\n')[0].Trim();System.Threading.Interlocked.Increment(ref Count);WebSocketNetwork.Write(stream,"HTTP/1.1 200 Connection Established\r\n\r\n");var bytes=new byte[256];int n;while((n=stream.Read(bytes,0,bytes.Length))>0){stream.Write(bytes,0,n);stream.Flush();}}catch(IOException){}}});}catch(SocketException){if(!done)throw;}catch(ObjectDisposedException){return;}});}
        public void Dispose(){done=true;server.Stop();}
    }
    internal static void Run(string directory){
        Directory.CreateDirectory(directory);var path=Path.Combine(directory,"websocket-fixture.json");var profile=new WebSocketSettings{httpPort=3067,httpHost="127.0.0.1"};Require(profile.websocketRepair&&profile.Resolve().Port==3067&&!profile.Independent,"Default WS proxy did not inherit HTTP");
        profile.wsProxyPort="7897";Require(profile.Resolve().Host=="127.0.0.1"&&profile.Resolve().Port==7897&&profile.Independent,"Independent WS port overwrote HTTP route");Require(profile.HttpProxy.Port==3067,"HTTP route changed");
        profile.Save(path);profile.wsProxyPort="7890";profile.Save(path);Require(WebSocketSettings.Load(path).wsProxyPort=="7890"&&WebSocketSettings.Load(path+".previous").wsProxyPort=="7897","Settings persistence/backup failed");
        profile.httpPort=0;bool invalid=false;try{profile.Resolve();}catch(ArgumentException){invalid=true;}Require(invalid,"Partial independent WS address accepted with HTTP off");profile.wsProxyHost="::1";Require(profile.Resolve().Host.Contains(":")&&profile.Resolve().Port==7890,"Independent IPv6 proxy not accepted");profile.wsProxyPort="65536";invalid=false;try{profile.Resolve();}catch(ArgumentException){invalid=true;}Require(invalid,"Invalid WS port accepted");profile.wsProxyPort="";profile.wsProxyHost="";Require(profile.Resolve()==null,"Direct mode manufactured a proxy");
        var originalBytes=File.ReadAllBytes(path);var prepared=new WebSocketSettings{httpPort=10808};WebSocketStartup.SavePrepared(prepared,path,"fixture");WebSocketStartup.SavePrepared(prepared,path,"fixture");var fakeState=path+".state";WebSocketStartup.Rollback(path,fakeState,null);Require(File.ReadAllBytes(path).SequenceEqual(originalBytes),"Repeated prepare lost pre-repair settings");WebSocketStartup.Rollback(path,fakeState,null);Require(File.ReadAllBytes(path).SequenceEqual(originalBytes),"Repeated rollback deleted restored settings");
        var doctor=new Dictionary<string,object>{{"checks",new Dictionary<string,object>{{"network.websocket_reachability",new Dictionary<string,object>{{"status","ok"},{"details",new Dictionary<string,object>{{"handshake result","HTTP 101 Switching Protocols"}}}}}}}};Require((bool)WebSocketStartup.ParseModelReport(doctor)["passed"],"Valid authenticated model WS handshake rejected");((Dictionary<string,object>)((Dictionary<string,object>)doctor["checks"])["network.websocket_reachability"])["details"]=new Dictionary<string,object>{{"handshake result","HTTP 403 Forbidden"}};Require(!(bool)WebSocketStartup.ParseModelReport(doctor)["passed"],"HTTP 403 model probe accepted as WS success");
        var manifest=new System.Xml.XmlDocument();manifest.LoadXml("<Application Executable='app/ChatGPT.exe'><Extensions><Extension Category='windows.appExecutionAlias'><AppExecutionAlias><ExecutionAlias Alias='chatgpt-desktop.exe'/></AppExecutionAlias></Extension><Extension Category='windows.appExecutionAlias' Executable='app/helper.exe'><AppExecutionAlias><ExecutionAlias Alias='helper.exe'/></AppExecutionAlias></Extension></Extensions></Application>");
        var alias=WebSocketApp.LaunchAliasFromManifest(manifest.DocumentElement,"OpenAI.Codex_26.1.0.0_x64__2p2nqsd0c76g0",directory);Require(alias==Path.Combine(directory,"Microsoft","WindowsApps","OpenAI.Codex_2p2nqsd0c76g0","chatgpt-desktop.exe"),"Official main-app execution alias was not selected");manifest.LoadXml("<Application Executable='app/ChatGPT.exe'/>");invalid=false;try{WebSocketApp.LaunchAliasFromManifest(manifest.DocumentElement,"OpenAI.Codex_26.1.0.0_x64__2p2nqsd0c76g0",directory);}catch(InvalidDataException){invalid=true;}Require(invalid,"Missing launch alias was accepted before app exit");
        var since=DateTime.Parse("2026-11-16T04:54:22Z",null,System.Globalization.DateTimeStyles.RoundtripKind);
        var connection=WebSocketStartup.ParseConnectionEvidence(new[]{"2026-11-16T04:54:33Z info remote_connections.connection_state_changed hostId=durable state=connected"},since);Require(Core.Value(connection,"state","")=="connected","Current desktop state=connected format was ignored");
        connection=WebSocketStartup.ParseConnectionEvidence(new[]{"2026-11-16T04:54:40Z info remote_connections.manager_state_set hostId=durable nextState=disconnected previousState=connected","2026-11-16T04:54:33Z info remote_connections.connection_state_changed hostId=durable state=connected"},since);Require(Core.Value(connection,"state","")=="disconnected","Newer disconnect was replaced by older connected log from another file");
        connection=WebSocketStartup.ParseConnectionEvidence(new[]{"2026-11-16T04:54:20Z info hostId=durable next=connected","2026-11-16T04:54:40Z info hostId=local state=connected"},since);Require(Core.Value(connection,"state","")=="unverified","Pre-launch or local host state accepted as remote connection");
        connection=WebSocketStartup.ParseConnectionEvidence(new[]{"2026-11-16T04:54:33Z info hostKind=durable currentState=connected","2026-11-16T04:54:41Z warning hostId=durable websocket_error HTTP 403"},since);Require(Core.Value(connection,"state","")!="connected"&&Core.Value(connection,"summary","").Contains("403"),"Remote error retained stale successful status");
        var options=Core.NormalizeOptions(new Dictionary<string,object>{{"wsProxyHost","127.0.0.1"},{"wsProxyPort","7897"}});Require((bool)options["websocketRepair"]&&Core.Value(options,"wsProxyPort","")=="7897","Worker discarded WS options");
        var info=WebSocketStartup.StartInfo(Core.Exe,new Uri("http://127.0.0.1:3067"));Require(info.EnvironmentVariables["NODE_USE_ENV_PROXY"]=="1"&&info.EnvironmentVariables["HTTPS_PROXY"]==info.EnvironmentVariables["https_proxy"]&&info.EnvironmentVariables["NO_PROXY"].Contains("127.0.0.1")&&!info.UseShellExecute,"Native launch did not carry proxy environment");
        using(var http=new FakeProxy())using(var ws=new FakeProxy())using(var relay=new WebSocketRelay(new Uri("http://127.0.0.1:"+http.Port),new Uri("http://127.0.0.1:"+ws.Port),"codex-cloud-backend.chatgpt.com",null)){
            relay.Start();var local=new Uri("http://127.0.0.1:"+relay.Port);foreach(var host in new[]{"codex-cloud-backend.chatgpt.com","chatgpt.com"})using(var client=WebSocketNetwork.Tunnel(local,host,443)){var stream=client.GetStream();var data=Encoding.ASCII.GetBytes("opaque-encrypted-data");stream.Write(data,0,data.Length);stream.Flush();var output=new byte[data.Length];int offset=0;while(offset<output.Length){int n=stream.Read(output,offset,output.Length-offset);if(n==0)break;offset+=n;}Require(offset==data.Length&&output.SequenceEqual(data),"Relay changed tunnel bytes");}
            Require(ws.Count==1&&http.Count==1&&ws.Target.Contains("codex-cloud-backend.chatgpt.com:443")&&http.Target.Contains("chatgpt.com:443"),"Dot and model destinations were not separated");
        }
        using(var wsProxy=new FakeProxy())using(var httpProxy=new FakeProxy()){
            var relayInfo=new ProcessStartInfo(Core.Exe,"--ws-relay"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var child=Process.Start(relayInfo)){
                child.StandardInput.WriteLine(Core.Json.Serialize(new {http="http://127.0.0.1:"+httpProxy.Port,websocket="http://127.0.0.1:"+wsProxy.Port,dotHost="codex-cloud-backend.chatgpt.com"}));child.StandardInput.Flush();var ready=child.StandardOutput.ReadLineAsync();Require(ready.Wait(5000),"Native relay did not report ready");var record=Core.ReadJson(ready.Result);child.Refresh();File.WriteAllText(Path.Combine(directory,"relay-resources.json"),Core.Json.Serialize(new {privateBytes=child.PrivateMemorySize64,workingSetBytes=child.WorkingSet64}));
                using(var owner=Process.Start(new ProcessStartInfo(Core.Exe,"--ws-fixture-owner"){UseShellExecute=false,CreateNoWindow=true})){
                    child.StandardInput.WriteLine(Core.Json.Serialize(new {pid=owner.Id,started=owner.StartTime.ToUniversalTime().Ticks,executable=Core.Exe}));child.StandardInput.Flush();child.StandardInput.Close();
                    using(var tunnel=WebSocketNetwork.Tunnel(new Uri("http://127.0.0.1:"+Core.Value(record,"port","0")),"codex-cloud-backend.chatgpt.com",443)){tunnel.GetStream().WriteByte(42);Require(tunnel.GetStream().ReadByte()==42,"Native helper did not forward tunnel");}
                    Require(wsProxy.Count==1&&httpProxy.Count==0,"Native helper mixed Dot and HTTP routes");owner.WaitForExit();Require(child.WaitForExit(5000)&&child.ExitCode==0,"Relay did not exit with its owner process");
                }
            }
        }
        var listener=new TcpListener(IPAddress.Loopback,0);try{listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;var response=Task.Run(()=>{using(var client=listener.AcceptTcpClient()){WebSocketNetwork.ReadHeader(client.GetStream());WebSocketNetwork.Write(client.GetStream(),"HTTP/1.1 403 Forbidden\r\nContent-Length: 0\r\n\r\n");}});invalid=false;try{using(WebSocketNetwork.Tunnel(new Uri("http://127.0.0.1:"+port),"fixture.invalid",443)){}}catch(IOException ex){invalid=ex.Message.Contains("403");}Require(invalid,"HTTP 403 was reported as successful WS tunnel");response.Wait();}finally{listener.Stop();}
    }
    static object Field(object target,string name){return target.GetType().GetField(name,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(target);}
    internal static void VerifyWindow(){var window=new MainWindow(true){Left=-20000,Top=-20000,ShowInTaskbar=false,Opacity=0};try{window.Show();var enabled=(CheckBox)Field(window,"proxyEnabled");var option=(CheckBox)Field(window,"websocketRepair");var host=(TextBox)Field(window,"wsProxyHost");var port=(TextBox)Field(window,"wsProxyPort");var effective=(TextBlock)Field(window,"wsEffective");Require(option.IsChecked==true&&port.Text.Length==0&&host.Text.Length==0,"WS default or empty override changed");enabled.IsChecked=false;Require(!option.IsEnabled,"Missing WS route was enabled");host.Text="127.0.0.1";port.Text="3067";Require(option.IsEnabled&&effective.Text.Contains("3067")&&effective.Text.Contains("独立"),"Independent WS route depended on HTTP switch");window.GetType().GetMethod("Navigate",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(window,new object[]{"连接与修复"});Require(host.Text=="127.0.0.1"&&port.Text=="3067","Page navigation discarded overrides");var field=(CheckBox)Field(window,"websocketEnabled");field.IsChecked=false;Require(option.IsChecked==false,"WS page toggle not synchronized with initialization");enabled.IsChecked=true;host.Text="";port.Text="";field.IsChecked=true;Require(effective.Text.Contains("沿用 HTTP"),"Clearing overrides did not restore inheritance");Require(window.UseLayoutRounding&&window.SnapsToDevicePixels,"Window DPI layout alignment missing");}finally{window.Close();}}
    internal static void Visual(string directory){
        var indicator=new ActivityIndicator{State="running",Width=36,Height=36};var panel=new StackPanel{Background=MorandiTheme.Canvas,Margin=new Thickness(0),Width=390,Height=210};panel.Children.Add(new Image{Source=Brand.VectorLogo,Width=40,Height=40,HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,0,0,12)});panel.Children.Add(indicator);panel.Children.Add(new TextBlock{Text="WebSocket 线路修复 · 正在处理",TextWrapping=TextWrapping.Wrap,Foreground=MorandiTheme.Text,FontSize=16,Margin=new Thickness(0,12,0,0)});var window=new Window{Content=panel,Width=390,Height=210,Left=-20000,Top=-20000,ShowInTaskbar=false,UseLayoutRounding=true};
        try{window.Show();window.UpdateLayout();Pump(100);Require(indicator.Animating==SystemParameters.ClientAreaAnimation,"Running indicator was not animated");double before=indicator.Angle;Pump(160);if(SystemParameters.ClientAreaAnimation)Require(Math.Abs(before-indicator.Angle)>1,"Spinner angle did not change");
            foreach(double scale in new[]{1,1.25,1.5,1.75,2,2.5,3}){var bitmap=new RenderTargetBitmap((int)(390*scale),(int)(210*scale),96*scale,96*scale,PixelFormats.Pbgra32);bitmap.Render(panel);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(directory,"dpi-"+(scale*100).ToString("0")+".png")))encoder.Save(file);}
            for(int i=0;i<18;i++){Pump(70);var bitmap=new RenderTargetBitmap(390,210,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(directory,"motion-"+i.ToString("00")+".png")))encoder.Save(file);}
            indicator.Visibility=Visibility.Collapsed;Pump(20);Require(!indicator.Animating,"Hidden indicator kept rotating");indicator.Visibility=Visibility.Visible;Pump(30);indicator.State="complete";Require(!indicator.Animating,"Completed indicator kept rotating");indicator.State="running";indicator.AllowMotion=false;Require(!indicator.Animating,"Reduced motion did not stop rotation");Require(Brand.VectorLogo is DrawingImage,"Sidebar logo is still a bitmap");
        }finally{window.Close();}
    }
    internal static void RecordInitialization(string directory){
        var window=new MainWindow(true){Width=1000,Height=740,Left=-20000,Top=-20000,ShowInTaskbar=false};
        try{var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;var progress=(InitializationProgress)Field(window,"initializationProgress");progress.Reset(Core.NormalizeOptions(new Dictionary<string,object>()),true);foreach(var stage in progress.Stages.Take(3))stage.State="complete";progress.Stages[3].State="running";progress.Stages[3].Detail="正在准备官方独立 CLI";window.GetType().GetField("busy",flags).SetValue(window,true);window.GetType().GetField("wizard",flags).SetValue(window,2);window.GetType().GetMethod("Navigate",flags).Invoke(window,new object[]{"初始化"});window.Show();window.UpdateLayout();foreach(var indicator in InitializationFlowTests.Descendants<ActivityIndicator>(window))indicator.AllowMotion=true;var bar=(ProgressBar)Field(window,"stageProgress");bar.BeginAnimation(System.Windows.Controls.Primitives.RangeBase.ValueProperty,new System.Windows.Media.Animation.DoubleAnimation(37.5,50,TimeSpan.FromSeconds(1.4)){EasingFunction=new System.Windows.Media.Animation.CubicEase{EasingMode=System.Windows.Media.Animation.EasingMode.EaseOut}});
            for(int i=0;i<30;i++){Pump(70);var view=(FrameworkElement)window.Content;var bitmap=new RenderTargetBitmap(1000,740,96,96,PixelFormats.Pbgra32);bitmap.Render(view);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(directory,"initialization-motion-"+i.ToString("00")+".png")))encoder.Save(file);}
        }finally{window.GetType().GetField("busy",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(window,false);window.Close();}
    }
    static void Pump(int milliseconds){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(milliseconds)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
}
